mapper.select:
SELECT * FROM samples
WHERE deleted = 0

    AND (
        MATCH(sample_name, material, description) AGAINST(#{keyword} IN BOOLEAN MODE)
        OR sample_code LIKE CONCAT('%', #{keywordRaw}, '%')
    )


    AND category = #{category}


    AND supplier LIKE CONCAT('%', #{supplier}, '%')

ORDER BY ${sortField} ${sortOrder}
